import { createRequire } from 'node:module';
import { mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const require = createRequire(import.meta.url);
const sharp = require(process.env.SHARP_MODULE || 'sharp');
const [source, outputBase] = process.argv.slice(2);
if (!source || !outputBase) {
  throw new Error('Usage: node scripts/export-carousel-poster.mjs <source.png> <output-prefix>');
}
await mkdir(dirname(resolve(outputBase)), { recursive: true });
// Artwork and lettering are generated by image_gen. This only exports the
// requested fixed banner dimensions and rounded-corner alpha at each density.
for (const scale of [1, 2, 3]) {
  const width = 678 * scale;
  const height = 214 * scale;
  const radius = 26 * scale;
  const mask = Buffer.from(`<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg"><rect width="${width}" height="${height}" rx="${radius}" fill="white"/></svg>`);
  const output = `${outputBase}@${scale}x.png`;
  await sharp(source)
    .resize(width, height, { fit: 'fill', kernel: 'lanczos3' })
    .ensureAlpha()
    .composite([{ input: mask, blend: 'dest-in' }])
    .png()
    .toFile(output);
  console.log(`${output}: ${width}×${height}, radius ${radius}`);
}
